function connect(isReconnect) {
  ws = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '/ws');
  ws.binaryType = 'arraybuffer';
  ws.onopen = () => {
    ws.send(JSON.stringify({type: 'join', name: myName, lang: myLang}));
    joined = true;
    el('joinbox').style.display = 'none';
    el('hdr').style.display = 'flex';
    el('microw').style.display = 'block';
    el('feed').style.display = 'block';
    // mac dinh doc bang ngon ngu minh noi; doi duoc bat cu luc nao
    el('displang').value = localStorage.getItem('dispLang') || myLang;
    el('displang').onchange = () => localStorage.setItem('dispLang', el('displang').value);
    setStatus(isReconnect ? 'Đã kết nối lại.' : 'Đã vào room. Bấm 🎙 để nói.');
    keepAwake();
    if (!isReconnect) fillMics();
  };
  ws.onmessage = e => handle(JSON.parse(e.data));
  ws.onclose = () => {
    if (!joined) return;
    // tu ket noi lai (dien thoai khoa man hinh / chap mang)
    setStatus('Mất kết nối — đang thử kết nối lại...');
    setTimeout(() => connect(true), 2000);
  };
  ws.onerror = () => { el('joinerr').textContent = 'Không kết nối được server.'; };
}

